sys_script.script:
(function executeRule(current, previous) {

    var INTERVIEW_TABLE =
        'x_snc_college_pl_0_interview';

    /* =====================================================
       NORMALIZE
       ===================================================== */

    function normalize(value) {

        return (
            (value || '')
                .toString()
                .toLowerCase()
                .replace(/[\s_-]/g, '')
                .trim()
        );
    }


    /* =====================================================
       CHECK APPLICATION STATUS
       ===================================================== */

    var currentStatusValue =
        current.getValue('status') || '';

    var currentStatusLabel =
        current.getDisplayValue('status') || '';

    var currentStatus =
        normalize(currentStatusValue);

    var currentLabel =
        normalize(currentStatusLabel);


    var isInterviewScheduled =
        currentStatus === 'interviewscheduled' ||
        currentLabel === 'interviewscheduled' ||
        currentStatus === 'scheduled' ||
        currentLabel === 'scheduled';


    if (!isInterviewScheduled) {
        return;
    }


    /* =====================================================
       ONLY WHEN STATUS CHANGES
       ===================================================== */

    if (previous) {

        var oldStatusValue =
            previous.getValue('status') || '';

        var oldStatusLabel =
            previous.getDisplayValue('status') || '';

        var oldStatus =
            normalize(oldStatusValue);

        var oldLabel =
            normalize(oldStatusLabel);


        var wasInterviewScheduled =
            oldStatus === 'interviewscheduled' ||
            oldLabel === 'interviewscheduled' ||
            oldStatus === 'scheduled' ||
            oldLabel === 'scheduled';


        /*
         * Already was Interview Scheduled.
         * Don't create another record unnecessarily.
         */

        if (wasInterviewScheduled) {
            return;
        }
    }


    /* =====================================================
       CHECK EXISTING INTERVIEW RECORD
       ===================================================== */

    var existing =
        new GlideRecord(INTERVIEW_TABLE);

    existing.addQuery(
        'application',
        current.getUniqueValue()
    );

    existing.query();


    /*
     * If an existing interview is still open,
     * don't create a duplicate.
     */

    while (existing.next()) {

        var existingStatus =
            normalize(
                existing.getDisplayValue('status')
            );

        var existingStatusValue =
            normalize(
                existing.getValue('status')
            );


        var completed =
            existingStatus.indexOf('completed') >= 0 ||
            existingStatus.indexOf('complete') >= 0 ||
            existingStatusValue.indexOf('completed') >= 0 ||
            existingStatusValue.indexOf('complete') >= 0;


        if (!completed) {

            return;
        }
    }


    /* =====================================================
       CREATE INTERVIEW
       ===================================================== */

    var interview =
        new GlideRecord(INTERVIEW_TABLE);

    interview.initialize();


    /* -----------------------------------------------------
       APPLICATION
       ----------------------------------------------------- */

    if (
        interview.isValidField('application')
    ) {

        interview.setValue(
            'application',
            current.getUniqueValue()
        );
    }


    /* -----------------------------------------------------
       DRIVE
       ----------------------------------------------------- */

    if (
        interview.isValidField('drive') &&
        current.isValidField('drive')
    ) {

        var driveId =
            current.getValue('drive');


        if (driveId) {

            interview.setValue(
                'drive',
                driveId
            );
        }
    }


    /* -----------------------------------------------------
       INTERVIEWER
       -----------------------------------------------------

       Leave empty.

       Admin/Interviewer will assign it
       from Interview Management.
       */

    if (
        interview.isValidField('interviewer')
    ) {

        interview.setValue(
            'interviewer',
            ''
        );
    }


    /* -----------------------------------------------------
       INTERVIEW DATE
       ----------------------------------------------------- */

    if (
        interview.isValidField('interview_date')
    ) {

        interview.setValue(
            'interview_date',
            ''
        );
    }


    /* -----------------------------------------------------
       ROUND
       -----------------------------------------------------

       Leave empty initially.

       Your Interview Management page can select
       Round 1 / Technical / HR / etc.
       */

    if (
        interview.isValidField('round_name')
    ) {

        interview.setValue(
            'round_name',
            ''
        );
    }


    /* -----------------------------------------------------
       RESULT
       ----------------------------------------------------- */

    if (
        interview.isValidField('result')
    ) {

        interview.setValue(
            'result',
            ''
        );
    }


    /* -----------------------------------------------------
       STATUS
       -----------------------------------------------------

       Try to find "Not Set" choice.

       If it doesn't exist, leave status blank.
       Your UI already displays blank status as
       "Not Set".
       */

    if (
        interview.isValidField('status')
    ) {

        var choice =
            new GlideRecord('sys_choice');


        choice.addQuery(
            'name',
            INTERVIEW_TABLE
        );


        choice.addQuery(
            'element',
            'status'
        );


        choice.addQuery(
            'inactive',
            false
        );


        choice.query();


        var notSetValue = '';


        while (choice.next()) {

            var choiceValue =
                normalize(
                    choice.getValue('value')
                );

            var choiceLabel =
                normalize(
                    choice.getValue('label')
                );


            if (
                choiceValue === 'notset' ||
                choiceLabel === 'notset' ||
                choiceValue.indexOf('notset') >= 0 ||
                choiceLabel.indexOf('notset') >= 0
            ) {

                notSetValue =
                    choice.getValue('value');

                break;
            }
        }


        if (notSetValue) {

            interview.setValue(
                'status',
                notSetValue
            );
        }
    }


    /* =====================================================
       INSERT
       ===================================================== */

    var interviewId =
        interview.insert();


    if (!interviewId) {

        gs.error(
            '[NEXORA] Failed to create Interview record for Application: ' +
            current.getDisplayValue()
        );

    } else {

        gs.info(
            '[NEXORA] Interview created successfully. ' +
            'Interview: ' +
            interviewId +
            ' | Application: ' +
            current.getDisplayValue()
        );
    }

})(current, previous);
